14	declare_lint_rule! {
15	    /// Disallow direct assignments to `document.cookie`.
16	    ///
17	    /// It's not recommended to use document.cookie directly as it's easy to get the string wrong.
18	    /// Instead, you should use the [Cookie Store API](https://developer.mozilla.org/en-US/docs/Web/API/CookieStore).
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```js,expect_diagnostic
25	    /// document.cookie = "foo=bar";
26	    /// ```
27	    ///
28	    /// ```js,expect_diagnostic
29	    /// document.cookie += "; foo=bar";
30	    /// ```
31	    ///
32	    /// ### Valid
33	    ///
34	    /// ```js
35	    /// const array = document.cookie.split("; ");
36	    /// ```
37	    ///
38	    /// ```js
39	    /// await cookieStore
40	    ///   .set({
41	    ///     name: "foo",
42	    ///     value: "bar",
43	    ///     expires: Date.now() + 24 * 60 * 60,
44	    ///     domain: "example.com",
45	    /// })
46	    /// ```
47	    ///
48	    /// ```js
49	    /// import Cookies from 'js-cookie';
50	    ///
51	    /// Cookies.set('foo', 'bar');
52	    /// ```
53	    ///
54	    pub NoDocumentCookie {
55	        version: "1.9.4",
56	        name: "noDocumentCookie",
57	        language: "js",
58	        sources: &[RuleSource::EslintUnicorn("no-document-cookie").same()],
59	        recommended: true,
60	        severity: Severity::Warning,
61	    }
62	}
