64	fn identifier_is_global_document(
65	    reference: &JsReferenceIdentifier,
66	    name: &StaticValue,
67	    model: &SemanticModel,
68	) -> bool {
69	    //  Check identifier is `document` and global
70	    name.text() == "document" && model.binding(reference).is_none()
71	}
