73	/// Check `expr` is `document`
74	fn is_global_document(expr: &AnyJsExpression, model: &SemanticModel) -> Option<()> {
75	    let (reference, name) = global_identifier(expr)?;
76	
77	    // `expr` is global document
78	    if identifier_is_global_document(&reference, &name, model) {
79	        Some(())
80	    } else {
81	        // Check binding declaration recursively
82	        let bind = model.binding(&reference)?;
83	        let decl = bind.tree().declaration()?;
84	        let decl = decl.parent_binding_pattern_declaration().unwrap_or(decl);
85	        match decl {
86	            // const foo = document;
87	            AnyJsBindingDeclaration::JsVariableDeclarator(declarator) => {
88	                let initializer = declarator.initializer()?;
89	                let right_expr = initializer.expression().ok()?;
90	                is_global_document(&right_expr, model)
91	            }
92	            _ => None,
93	        }
94	    }
95	}
