97	/// Check member is `cookie`
98	fn is_cookie(assignment: &AnyJsAssignment) -> Option<()> {
99	    const COOKIE: &str = "cookie";
100	    match assignment {
101	        // `document.cookie`
102	        AnyJsAssignment::JsStaticMemberAssignment(static_assignment) => {
103	            let property = static_assignment.member().ok()?;
104	
105	            if property.to_trimmed_text().text() != COOKIE {
106	                return None;
107	            };
108	        }
109	        // `document["cookie"]`
110	        AnyJsAssignment::JsComputedMemberAssignment(computed_assignment) => {
111	            let any_expr = computed_assignment.member().ok()?;
112	            let string_literal = any_expr
113	                .as_any_js_literal_expression()?
114	                .as_js_string_literal_expression()?;
115	            let inner_string = string_literal.inner_string_text().ok()?;
116	
117	            if inner_string.text() != COOKIE {
118	                return None;
119	            }
120	        }
121	        _ => {
122	            return None;
123	        }
124	    }
125	
126	    Some(())
127	}
