129	impl Rule for NoDocumentCookie {
130	    type Query = Semantic<JsAssignmentExpression>;
131	    type State = ();
132	    type Signals = Option<Self::State>;
133	    type Options = NoDocumentCookieOptions;
134	
135	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
136	        let node = ctx.query();
137	
138	        let left = node.left().ok()?;
139	
140	        let any_assignment = left.as_any_js_assignment()?;
141	
142	        let expr = match any_assignment {
143	            AnyJsAssignment::JsStaticMemberAssignment(assignment) => assignment.object().ok()?,
144	            AnyJsAssignment::JsComputedMemberAssignment(assignment) => assignment.object().ok()?,
145	            _ => {
146	                return None;
147	            }
148	        };
149	
150	        is_global_document(&expr, ctx.model())?;
151	
152	        is_cookie(any_assignment)?;
153	
154	        Some(())
155	    }
