157	    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
158	        let node = ctx.query();
159	        Some(
160	            RuleDiagnostic::new(
161	                rule_category!(),
162	                node.range(),
163	                markup! {
164	                    "Direct assigning to "<Emphasis>"document.cookie"</Emphasis>" is not recommended."
165	                },
166	            )
167	            .note(markup! {
168	                "Consider using the "<Hyperlink href = "https://developer.mozilla.org/en-US/docs/Web/API/CookieStore">"Cookie Store API"</Hyperlink>"."
169	            }),
170	        )
171	    }
172	}
