1912	/// Check if `expr` refers to a name that is directly referenced or indirectly via `globalThis` or `window`.
1913	/// Returns the reference and the name.
1914	///
1915	/// ### Examples
1916	///
1917	/// ```
1918	/// use biome_js_syntax::{AnyJsExpression, AnyJsLiteralExpression, AnyJsMemberExpression, global_identifier, T};
1919	/// use biome_js_factory::make;
1920	///
1921	/// let math_reference = make::js_reference_identifier(make::ident("Math"));
1922	/// let math_id = make::js_identifier_expression(math_reference.clone());
1923	/// let math_id = AnyJsExpression::from(math_id);
1924	/// let (reference, name) = global_identifier(&math_id).unwrap();
1925	/// assert_eq!(name.text(), "Math");
1926	/// assert_eq!(reference, math_reference);
1927	///
1928	/// let global_this_reference = make::js_reference_identifier(make::ident("globalThis"));
1929	/// let global_this_id = make::js_identifier_expression(global_this_reference.clone());
1930	/// let global_this_id = AnyJsExpression::from(global_this_id);
1931	///
1932	/// let math_ident_token = make::ident("Math");
1933	/// let math_name = make::js_name(math_ident_token);
1934	/// let static_member = make::js_static_member_expression(global_this_id.clone().into(), make::token(T![.]), math_name.into());
1935	/// let static_member = AnyJsExpression::from(static_member);
1936	/// let (reference, name) = global_identifier(&static_member).unwrap();
1937	/// assert_eq!(name.text(), "Math");
1938	/// assert_eq!(reference, global_this_reference);
1939	/// ```
1940	pub fn global_identifier(expr: &AnyJsExpression) -> Option<(JsReferenceIdentifier, StaticValue)> {
1941	    if let Some(reference) = expr.as_js_reference_identifier() {
1942	        let name = StaticValue::String(reference.value_token().ok()?);
1943	        return Some((reference, name));
1944	    }
1945	    let member_expr = AnyJsMemberExpression::cast_ref(expr.syntax())?;
1946	    let name = member_expr.member_name()?;
1947	    let mut expr = member_expr.object().ok()?.omit_parentheses();
1948	    while let Some(member_expr) = AnyJsMemberExpression::cast_ref(expr.syntax()) {
1949	        if !matches!(member_expr.member_name()?.text(), GLOBAL_THIS | WINDOW) {
1950	            return None;
1951	        }
1952	        expr = member_expr.object().ok()?.omit_parentheses();
1953	    }
1954	    if let Some(reference) = expr.as_js_reference_identifier()
1955	        && matches!(reference.name().ok()?.text(), GLOBAL_THIS | WINDOW)
1956	    {
1957	        return Some((reference, name));
1958	    }
1959	    None
1960	}
