const IMPLIED_EVAL_FUNCTIONS: &[&str] = &["setTimeout", "setInterval", "setImmediate"];

declare_lint_rule! {
    /// Disallow the use of `eval()`-like methods.
    ///
    /// It's not recommended to use `setTimeout()`, `setInterval()`, or `setImmediate()` with a
    /// string as the first argument. Passing a string causes the string to be evaluated using
    /// `eval()`, which is a form of implied `eval()`. This is a potential security risk and it
    /// prevents optimizations by the JavaScript engine. A function should be passed instead.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// setTimeout("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// setInterval("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// setImmediate("alert('Hi!')");
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// window.setTimeout("count = 5", 10);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// setTimeout(function () {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    /// ```js
    /// setInterval(() => {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    /// ```js
    /// setTimeout(`${foo}`, 100);
    /// ```
    ///
    pub NoImpliedEval {
        version: "next",
        name: "noImpliedEval",
        language: "js",
        sources: &[RuleSource::Eslint("no-implied-eval").same()],
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for NoImpliedEval {
    type Query = Semantic<JsCallExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoImpliedEvalOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call = ctx.query();
        let model = ctx.model();

        let callee = call.callee().ok()?;
        if !is_implied_eval_callee(&callee, model) {
            return None;
        }

        let first_argument = call
            .arguments()
            .ok()?
            .args()
            .first()?
            .ok()?
            .as_any_js_expression()?
            .clone();

        if is_string_expression(&first_argument) {
            Some(())
        } else {
            None
        }
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let call = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                call.range(),
                markup! {
                    "Implied eval() is not allowed."
                },
            )
            .note(markup! {
                "Passing strings to functions like setTimeout, setInterval, or setImmediate is a form of implied eval() and can lead to security and performance issues."
            })
            .note(markup! {
                "Use a function instead of a string."
            }),
        )
    }
}

/// Checks whether `callee` refers to one of the implied-eval functions
/// (`setTimeout`, `setInterval`, `setImmediate`), either as a global
/// identifier or accessed through `window`/`globalThis`.
///
/// The reference must not be shadowed by a local binding.
fn is_implied_eval_callee(callee: &AnyJsExpression, model: &SemanticModel) -> bool {
    let Some((reference, name)) = global_identifier(callee) else {
        return false;
    };

    IMPLIED_EVAL_FUNCTIONS.contains(&name.text()) && model.binding(&reference).is_none()
}

/// Checks whether `expr` is a string expression: a string literal, a template
/// literal without substitutions, a string concatenation, or any of these
/// wrapped in parentheses.
fn is_string_expression(expr: &AnyJsExpression) -> bool {
    match expr {
        AnyJsExpression::JsParenthesizedExpression(paren) => paren
            .expression()
            .is_ok_and(|inner| is_string_expression(&inner)),
        AnyJsExpression::AnyJsLiteralExpression(
            AnyJsLiteralExpression::JsStringLiteralExpression(_),
        ) => true,
        AnyJsExpression::JsTemplateExpression(template) => {
            // Only untagged template literals without substitutions are static strings.
            template.tag().is_none()
                && !template.elements().into_iter().any(|element| {
                    matches!(element, AnyJsTemplateElement::JsTemplateElement(_))
                })
        }
        AnyJsExpression::JsBinaryExpression(binary) => {
            if binary.operator() != Ok(JsBinaryOperator::Plus) {
                return false;
            }
            let left = binary.left().ok();
            let right = binary.right().ok();
            left.is_some_and(|expr| is_string_expression(&expr))
                || right.is_some_and(|expr| is_string_expression(&expr))
        }
        _ => false,
    }
}
